const item = $input.first();
const jobDescription = item.json.jobDescription ?? '';
const binary = item.binary ?? {};
const fileKeys = Object.keys(binary).filter((key) => {
  const normalized = key.toLowerCase();
  return normalized === 'applications' || normalized.startsWith('applications');
});
fileKeys.sort();
if (fileKeys.length === 0) {
  throw new Error('No application files found in the form submission.');
}
return fileKeys.map((key, index) => {
  const fileBinary = binary[key];
  const fileName = fileBinary?.fileName ?? fileBinary?.file_name ?? key;
  return {
    json: {
      jobDescription,
      documentNumber: index + 1,
      sourceFileKey: key,
      fileName,
    },
    binary: {
      data: fileBinary,
    },
  };
});

const jobDescription = $('Split Applications').first().json.jobDescription;
const items = $input.all().sort((a, b) => (a.json.documentNumber ?? 0) - (b.json.documentNumber ?? 0));
const sections = [];
const documentFileNames = [];
for (const item of items) {
  const num = item.json.documentNumber;
  const text = (item.json.text ?? '').trim();
  if (!text) {
    throw new Error('Empty text after PDF extraction for document ' + num);
  }
  sections.push('--- DOCUMENT ' + num + ' ---\n' + text);
  documentFileNames.push({
    documentNumber: num,
    fileName: item.json.fileName ?? 'document-' + num + '.pdf',
  });
}
return [{
  json: {
    jobDescription,
    documentCount: items.length,
    combinedText: sections.join('\n\n'),
    documentFileNames,
  },
}];

const source = $('Concatenate Texts').first().json;
const anonymized = $input.first().json;
return [{
  json: {
    jobDescription: source.jobDescription,
    documentCount: source.documentCount,
    pseudonymizedApplications: anonymized.pseudonymizedText,
    piiMappings: anonymized.detection ?? anonymized.piis ?? null,
  },
}];

const prepared = $('Prepare Anonymization').first().json;
const mergeData = $('Concatenate Texts').first().json;
const agentOutput = $input.first().json.output ?? {};

const fileNameByDoc = {};
for (const entry of mergeData.documentFileNames ?? []) {
  fileNameByDoc[entry.documentNumber] = entry.fileName;
}

const detections = prepared.piiMappings?.detections ?? [];
const pseudonymToText = {};
for (const detection of detections) {
  if (detection?.pseudonym && detection?.text) {
    pseudonymToText[detection.pseudonym] = detection.text;
  }
}

const pseudonymsByLength = Object.keys(pseudonymToText).sort((a, b) => b.length - a.length);

function deanonymizeJustification(text) {
  if (!text) {
    return text;
  }
  let result = text;
  for (const pseudonym of pseudonymsByLength) {
    const escaped = pseudonym.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    result = result.replace(new RegExp(escaped, 'g'), pseudonymToText[pseudonym]);
  }
  return result;
}

const ranking = (agentOutput.ranking ?? []).map((row) => {
  const justificationPseudonymized = row.justification ?? '';
  return {
    documentNumber: row.documentNumber,
    fileName: fileNameByDoc[row.documentNumber] ?? null,
    justificationPseudonymized,
    justification: deanonymizeJustification(justificationPseudonymized),
  };
});

return [{
  json: {
    jobDescription: prepared.jobDescription,
    documentCount: prepared.documentCount,
    ranking,
  },
}];

const result = $input.first().json;
const ranking = result.ranking ?? [];
if (ranking.length === 0) {
  throw new Error('Ranking contains no entries.');
}

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const rows = ranking.map((entry, index) => {
  const place = index + 1;
  const fileName = escapeHtml(entry.fileName ?? 'Unknown file');
  const justification = escapeHtml(entry.justification ?? '');
  const topMark = place === 1 ? ' &#9733;' : '';
  return '<tr>'
    + '<td><strong>' + place + '</strong></td>'
    + '<td>' + fileName + topMark + '</td>'
    + '<td>' + justification + '</td>'
    + '</tr>';
}).join('\n');

const htmlReport = '<div>'
  + '<h1>HR CV Ranker – Results</h1>'
  + '<p><strong>' + ranking.length + '</strong> application(s), sorted by fit (rank 1 = best).</p>'
  + '<table border="1" cellpadding="12" cellspacing="0">'
  + '<thead><tr>'
  + '<th align="left">Rank</th>'
  + '<th align="left">File</th>'
  + '<th align="left">Justification</th>'
  + '</tr></thead>'
  + '<tbody>'
  + rows
  + '</tbody></table>'
  + '</div>';

return [{
  json: {
    ...result,
    htmlReport,
  },
}];
